# Initially generated by GitHub Copilot.
"""Generate and write doc/mp-claims.md from the registered claim registry."""

from typing import Mapping

from author_util.claim import ClaimCollection, ClaimRecord
from verify_mp import driver as _driver
from verify_mp import verifiers_plus, verifiers_both, verifiers_plain

_OUT_PATH = "doc/mp-claims.md"

_VERIFIER_MODULES = (verifiers_plus, verifiers_both, verifiers_plain)


def _find_verifier_fn(claim_id: str):
    """Return the verifier function for claim_id, or None if pending."""
    fn_name = _driver.claim_id_to_fn_name(claim_id)
    for mod in _VERIFIER_MODULES:
        fn = getattr(mod, fn_name, None)
        if fn is not None:
            return fn
    return None


def _fn_docstring(fn) -> str:
    """Return first paragraph of fn's docstring, collapsed to one line."""
    doc = fn.__doc__ or ""
    first_para = doc.split("\n\n")[0]
    return " ".join(first_para.split())


def _records_by_id(
    claims: ClaimCollection | Mapping[str, ClaimRecord] | None,
) -> Mapping[str, ClaimRecord]:
    if claims is None:
        from author_util.claim import REGISTRY

        return REGISTRY
    if isinstance(claims, ClaimCollection):
        return claims.records_by_id
    return claims


def generate(claims: ClaimCollection | Mapping[str, ClaimRecord] | None = None) -> str:
    """Return the full Markdown text for doc/mp-claims.md."""
    records = _records_by_id(claims)

    lines = [
        "<!-- Initially generated by GitHub Copilot. -->",
        "# MAM-parsed claims index",
        "",
        "Auto-generated by `py/main_authored.py gen-mp-claims-index`. Do not edit by hand.",
        "",
        "| Claim id | Kind | Subject | Defined in | Verifier | Verifier docstring |",
        "| --- | --- | --- | --- | --- | --- |",
    ]

    for _claim_id, record in sorted(records.items()):
        fn = _find_verifier_fn(record.id)
        if fn is not None:
            fn_name = fn.__name__
            docstring = _fn_docstring(fn)
        else:
            fn_name = "pending"
            docstring = ""

        # Escape pipe characters in any cell that might contain them.
        def esc(s: str) -> str:
            return s.replace("|", "\\|")

        lines.append(
            f"| {esc(record.id)} "
            f"| {esc(record.kind)} "
            f"| {esc(record.subject)} "
            f"| {esc(record.defined_in)} "
            f"| {esc(fn_name)} "
            f"| {esc(docstring)} |"
        )

    lines.append("")
    return "\n".join(lines)


def write_output(
    claims: ClaimCollection | Mapping[str, ClaimRecord] | None = None,
    path: str = _OUT_PATH,
    *,
    populate_registry: bool = True,
) -> str:
    """Write claims index markdown and return output path.

    By default this populates the registry first. Callers that already produced
    all claim registrations in-process (for example doc-generation commands that
    invoke section builders) can pass populate_registry=False.
    """
    if claims is None and populate_registry:
        from verify_mp import registry_load

        registry_load.populate()
    text = generate(claims)
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(text)
    return path
